-- November 2026: Novelle by Grazia Deledda, source order 00..13.
-- Run only after all fourteen audio objects pass upload-verification.json.
begin;
insert into public.audiobooks (slug, title, author, narrator, category, description, total_duration_seconds, cover_from, cover_via, cover_to, vibe, is_published)
select slug, title, author, narrator, category, description, total_duration_seconds, cover_from, cover_via, cover_to, vibe, is_published
from jsonb_to_recordset($books$[{"slug": "novelle", "title": "Novelle", "author": "Grazia Deledda", "narrator": "Antonella Civale", "category": "Narrativa", "description": "Una selezione di quattordici novelle di Grazia Deledda, da La volpe a L’ultima. Un viaggio nella Sardegna dei paesi, tra rapporti familiari, fede, desideri e contrasti sociali. La voce di Antonella Civale accompagna l’ascolto di storie in cui la vita quotidiana si intreccia con passioni, segreti e destini inattesi.", "vibe": "Novelle, Sardegna, affetti e contrasti sociali", "cover_from": "#3e5144", "cover_via": "#91a58b", "cover_to": "#1a2821", "is_published": true, "total_duration_seconds": 17879}]$books$::jsonb)
as b(slug text, title text, author text, narrator text, category text, description text,
     total_duration_seconds integer, cover_from text, cover_via text, cover_to text, vibe text, is_published boolean)
on conflict (slug) do update set
title = excluded.title, author = excluded.author, narrator = excluded.narrator, category = excluded.category, description = excluded.description, total_duration_seconds = excluded.total_duration_seconds, cover_from = excluded.cover_from, cover_via = excluded.cover_via, cover_to = excluded.cover_to, vibe = excluded.vibe, is_published = excluded.is_published;
insert into public.chapters (book_id, slug, chapter_index, title, duration_seconds, audio_url)
select b.id, c.chapter_slug, c.chapter_index, c.chapter_title, c.duration_seconds, c.audio_url
from jsonb_to_recordset($chapters$[{"book_slug": "novelle", "chapter_index": 1, "chapter_slug": "la-volpe", "chapter_title": "La volpe", "duration_seconds": 1809, "r2_key": "novelle/00-la-volpe.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/00-la-volpe.wav"}, {"book_slug": "novelle", "chapter_index": 2, "chapter_slug": "chiaroscuro", "chapter_title": "Chiaroscuro", "duration_seconds": 1138, "r2_key": "novelle/01-chiaroscuro.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/01-chiaroscuro.wav"}, {"book_slug": "novelle", "chapter_index": 3, "chapter_slug": "le-tredici-uova", "chapter_title": "Le tredici uova", "duration_seconds": 1193, "r2_key": "novelle/02-le-tredici-uova.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/02-le-tredici-uova.wav"}, {"book_slug": "novelle", "chapter_index": 4, "chapter_slug": "la-porta-aperta", "chapter_title": "La porta aperta", "duration_seconds": 1351, "r2_key": "novelle/03-la-porta-aperta.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/03-la-porta-aperta.wav"}, {"book_slug": "novelle", "chapter_index": 5, "chapter_slug": "la-porta-chiusa", "chapter_title": "La porta chiusa", "duration_seconds": 1164, "r2_key": "novelle/04-la-porta-chiusa.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/04-la-porta-chiusa.wav"}, {"book_slug": "novelle", "chapter_index": 6, "chapter_slug": "il-natale-del-consigliere", "chapter_title": "Il Natale del consigliere", "duration_seconds": 1582, "r2_key": "novelle/05-il-natale-del-consigliere.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/05-il-natale-del-consigliere.wav"}, {"book_slug": "novelle", "chapter_index": 7, "chapter_slug": "al-servizio-del-re", "chapter_title": "Al servizio del re", "duration_seconds": 868, "r2_key": "novelle/06-al-servizio-del-re.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/06-al-servizio-del-re.wav"}, {"book_slug": "novelle", "chapter_index": 8, "chapter_slug": "padrona-e-servi", "chapter_title": "Padrona e servi", "duration_seconds": 1435, "r2_key": "novelle/07-padrona-e-servi.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/07-padrona-e-servi.wav"}, {"book_slug": "novelle", "chapter_index": 9, "chapter_slug": "la-scomunica", "chapter_title": "La scomunica", "duration_seconds": 1274, "r2_key": "novelle/08-la-scomunica.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/08-la-scomunica.wav"}, {"book_slug": "novelle", "chapter_index": 10, "chapter_slug": "l-uomo-nuovo", "chapter_title": "L’uomo nuovo", "duration_seconds": 1312, "r2_key": "novelle/09-l-uomo-nuovo.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/09-l-uomo-nuovo.wav"}, {"book_slug": "novelle", "chapter_index": 11, "chapter_slug": "la-cerbiatta", "chapter_title": "La cerbiatta", "duration_seconds": 903, "r2_key": "novelle/10-la-cerbiatta.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/10-la-cerbiatta.wav"}, {"book_slug": "novelle", "chapter_index": 12, "chapter_slug": "la-festa-del-cristo", "chapter_title": "La festa del Cristo", "duration_seconds": 1766, "r2_key": "novelle/11-la-festa-del-cristo.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/11-la-festa-del-cristo.wav"}, {"book_slug": "novelle", "chapter_index": 13, "chapter_slug": "un-po-a-tutti", "chapter_title": "Un po’ a tutti", "duration_seconds": 1100, "r2_key": "novelle/12-un-po-a-tutti.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/12-un-po-a-tutti.wav"}, {"book_slug": "novelle", "chapter_index": 14, "chapter_slug": "l-ultima", "chapter_title": "L’ultima", "duration_seconds": 984, "r2_key": "novelle/13-l-ultima.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/novelle/13-l-ultima.wav"}]$chapters$::jsonb)
as c(book_slug text, chapter_index integer, chapter_slug text, chapter_title text, duration_seconds integer, r2_key text, audio_url text)
join public.audiobooks b on b.slug = c.book_slug
on conflict (book_id, slug) do update set chapter_index=excluded.chapter_index, title=excluded.title,
duration_seconds=excluded.duration_seconds, audio_url=excluded.audio_url;
commit;
select b.slug, b.title, b.category, b.narrator, b.is_published, b.total_duration_seconds,
       count(c.id) as tracks, array_agg(c.title order by c.chapter_index) as ordered_chapters
from public.audiobooks b join public.chapters c on c.book_id=b.id
where b.slug = 'novelle'
group by b.id order by b.slug;
